  /* ---- hero character visual ---- */
  .wt-hero-visual { position: absolute; inset: 0; pointer-events: none; z-index: 1; -webkit-mask-image: linear-gradient(90deg, transparent 0%, transparent 6%, black 28%); mask-image: linear-gradient(90deg, transparent 0%, transparent 6%, black 28%); }
  .wt-hero-visual img { position: absolute; inset: 0; width: 100%; height: 100%; mix-blend-mode: screen; }
  .wt-hero-visual img { object-fit: cover; object-position: right bottom; display: block; filter: contrast(1.3); }



  /* ---- distressed display face for section titles --------------------------
     Love Letter TW (free, by Dixie's Delights): https://www.dafont.com/love-letter-tw.font
     File: comp/fonts/Lovelt__.ttf  ·  fallback = Special Elite if ever missing. */
  @font-face {
    font-family: 'Love Letter TW';
    src: url("data:font/ttf;base64,") format('truetype');
    font-weight: 400 900; font-style: normal; font-display: swap;
  }



  :root {
    --wt-accent: #8fbf9f;
    --wt-wordmark: 'Zen Old Mincho';
    --wt-red: #c08a82;
    --wt-blue: #8a9cc0;
    --wt-pink: #c47898;
  }
  * { box-sizing: border-box; }
  html, body { margin: 0; padding: 0; background: #0a0b0e; overflow-x: hidden; }
  body { -webkit-font-smoothing: antialiased; }
  ::selection { background: rgba(143,191,159,0.25); color: #e6e1d4; }

  /* ---- ticker marquee ---- */
  @keyframes wt-marq { from { transform: translate3d(0,0,0); } to { transform: translate3d(-50%,0,0); } }
  .wt-track { display: inline-flex; white-space: nowrap; animation: wt-marq 34s linear infinite; will-change: transform; }

  /* ---- blinking cursor ---- */
  @keyframes wt-blink { 0%, 48% { opacity: 1; } 49%, 100% { opacity: 0; } }
  .wt-cursor { animation: wt-blink 1.05s steps(1) infinite; }

  /* ---- pulsing node dot ---- */
  @keyframes wt-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.25; } }
  .wt-pulse { animation: wt-pulse 1.8s ease-in-out infinite; }

  /* ---- CRT flicker overlay ---- */
  @keyframes wt-flick { 0%,19%,21%,55%,57%,100% { opacity: 0.012; } 20% { opacity: 0.04; } 56% { opacity: 0.03; } }
  .wt-flicker { animation: wt-flick 7s steps(1) infinite; }

  /* ---- slow ken-burns drift on cinematic plates ---- */
  @keyframes wt-kb { 0% { transform: scale(1.04) translate(0,0); } 100% { transform: scale(1.12) translate(-1.5%, -1.5%); } }
  .wt-kenburns { animation: wt-kb 26s ease-in-out infinite alternate; transform-origin: center; }

  /* ---- uplink meter bars ---- */
  @keyframes wt-uplink { 0%,100% { transform: scaleY(0.5); } 50% { transform: scaleY(1); } }
  .wt-uplink-bar { transform-origin: bottom; animation: wt-uplink 1.6s ease-in-out infinite; }

  /* ---- RGB-split glitch wordmark ---- */
  .wt-glitch { position: relative; }
  .wt-glitch::before, .wt-glitch::after {
    content: attr(data-text); position: absolute; left: 0; top: 0; width: 100%; height: 100%;
    pointer-events: none; mix-blend-mode: screen; opacity: 0.55;
  }
  .wt-glitch::before { color: var(--wt-red); animation: wt-gl1 7s steps(1) infinite; }
  .wt-glitch::after  { color: var(--wt-blue); animation: wt-gl2 7s steps(1) infinite; }
  @keyframes wt-gl1 {
    0%, 90%, 100% { transform: translate(0,0); clip-path: inset(0 0 0 0); }
    91% { transform: translate(-3px, 1px); clip-path: inset(0 0 62% 0); }
    93% { transform: translate(2px, -1px); clip-path: inset(20% 0 40% 0); }
    95% { transform: translate(-2px, 0); clip-path: inset(55% 0 8% 0); }
    97% { transform: translate(1px, 1px); clip-path: inset(0 0 0 0); }
  }
  @keyframes wt-gl2 {
    0%, 90%, 100% { transform: translate(0,0); clip-path: inset(0 0 0 0); }
    91% { transform: translate(3px, -1px); clip-path: inset(50% 0 12% 0); }
    93% { transform: translate(-2px, 1px); clip-path: inset(8% 0 64% 0); }
    95% { transform: translate(2px, 0); clip-path: inset(30% 0 30% 0); }
    97% { transform: translate(-1px, -1px); clip-path: inset(0 0 0 0); }
  }

  /* ---- buttons ---- */
  .wt-btn-ghost:hover { background: var(--wt-accent) !important; color: #0a0b0e !important; border-color: var(--wt-accent) !important; box-shadow: 0 0 18px rgba(143,191,159,0.25); }
  .wt-btn-primary:hover { background: transparent !important; color: var(--wt-accent) !important; border-color: var(--wt-accent) !important; box-shadow: 0 0 18px rgba(143,191,159,0.15); }
  .wt-btn:active { transform: translateY(1px); }
  .wt-flink { transition: color .15s; position: relative; }
  .wt-flink:hover { color: var(--wt-accent) !important; }

  /* ---- focus ---- */
  *:focus-visible {
    outline: 2px solid var(--wt-accent);
    outline-offset: 2px;
    box-shadow: 0 0 0 4px rgba(143,191,159,0.14);
  }

  /* ---- tweak toggles ---- */
  body.no-scan .wt-scan { display: none !important; }
  body.no-grain .wt-grain { display: none !important; }
  body.no-motion .wt-track,
  body.no-motion .wt-cursor,
  body.no-motion .wt-pulse,
  body.no-motion .wt-flicker,
  body.no-motion .wt-kenburns,
  body.no-motion .wt-uplink-bar,
  body.no-motion .wt-glitch::before,
  body.no-motion .wt-glitch::after { animation: none !important; }
  body.no-motion .wt-glitch::before, body.no-motion .wt-glitch::after { opacity: 0; }

  @media (prefers-reduced-motion: reduce) {
    .wt-track, .wt-kenburns, .wt-uplink-bar, .wt-glitch::before, .wt-glitch::after, .wt-flicker { animation: none !important; }
  }

.wt-scene-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  min-height: 300px;
  align-content: start;
}
@media (min-width: 600px) {
  .wt-scene-grid { grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); }
}


